"use client"

import { forwardRef, useId, useImperativeHandle, type ReactNode } from "react"

import {
  usePercentInput,
  type UsePercentInputOptions,
} from "./use-percent-input"

export interface PercentInputProps extends UsePercentInputOptions {
  /** Visible label. Supply this or `aria-label` — a field with neither has no accessible name. */
  label?: ReactNode
  /** Helper text under the field. Replaced by the error message while one is showing. */
  hint?: ReactNode
}

/**
 * A percentage field.
 *
 * Displays `12.5`, emits `0.125`. The off-by-100 bug, solved once.
 */
export const PercentInput = forwardRef<HTMLInputElement, PercentInputProps>(
  function PercentInput({ label, hint, className, id: idProp, ...rest }, ref) {
    const reactId = useId()
    const id = idProp ?? reactId

    const api = usePercentInput({ ...rest, id })
    const {
      inputProps,
      ariaProps,
      containerProps,
      hiddenInputProps,
      ownsErrorUI,
      errorText,
      errorId,
      visible,
    } = api

    useImperativeHandle(
      ref,
      () =>
        inputProps.ref.current ??
        ({ focus: () => inputProps.ref.current?.focus() } as HTMLInputElement),
      [inputProps.ref],
    )

    return (
      <div className={`inputcn-field ${className ?? ""}`.trim()} {...containerProps}>
        {label === undefined ? null : (
          <label className="inputcn-label" htmlFor={id}>
            {label}
          </label>
        )}

        <div
          className="inputcn-group"
          data-invalid={ariaProps["aria-invalid"] ? "true" : undefined}
        >
          <input
            {...inputProps}
            {...ariaProps}
            id={id}
            className="inputcn-bare inputcn-numeric"
            aria-label={rest["aria-label"]}
            aria-labelledby={rest["aria-labelledby"]}
          />
          <span className="inputcn-affix inputcn-affix-right" aria-hidden="true">
            %
          </span>
        </div>

        {ownsErrorUI && errorText ? (
          <p
            id={errorId}
            className={visible?.warning ? "inputcn-warning" : "inputcn-error"}
            // Stable rule name so a test can assert WHICH rule failed rather
            // than matching copy, which breaks on a rewrite or a locale change.
            data-rule={visible?.rule}
            role="alert"
          >
            {errorText}
          </p>
        ) : hint !== undefined ? (
          <p className="inputcn-hint">{hint}</p>
        ) : null}

        {hiddenInputProps ? <input {...hiddenInputProps} /> : null}
      </div>
    )
  },
)

"use client"

import { useCallback, useMemo, useRef, useState, type ClipboardEvent } from "react"

import { clipboardText } from "@inputcn/core/paste"
import type { BaseFieldProps, Rule } from "@inputcn/core/types"
import { useField, type UseFieldResult } from "@inputcn/core/use-field"
import {
  custom,
  integer as integerRule,
  max as maxRule,
  min as minRule,
  positive as positiveRule,
  required as requiredRule,
  rules,
} from "@inputcn/core/validity"

import {
  formatPercent,
  parsePastedPercent,
  parsePercent,
  withinPrecision,
} from "./percent"

export interface PercentConstraints {
  /** As a fraction: 0.05 means 5%. */
  min?: number
  /** As a fraction: 1 means 100%. */
  max?: number
  positive?: boolean
  /** Reject fractional percentages — 12% yes, 12.5% no. */
  integer?: boolean
  /** Maximum decimal places in the displayed percentage. Default 2. */
  precision?: number
}

export interface UsePercentInputOptions
  extends BaseFieldProps<number>,
    PercentConstraints {
  locale?: string
}

export interface UsePercentInputResult extends UseFieldResult<number> {
  /** The percentage string currently shown. */
  display: string
  inputProps: {
    ref: React.RefObject<HTMLInputElement | null>
    value: string
    onChange: (e: React.ChangeEvent<HTMLInputElement>) => void
    onBlur: () => void
    onPaste: (e: ClipboardEvent<HTMLInputElement>) => void
    inputMode: "decimal"
    autoComplete: "off"
    disabled: boolean | undefined
    readOnly: boolean | undefined
    placeholder: string | undefined
  }
}

const ALLOWED = /^[\d.,]*$/

export function usePercentInput(
  options: UsePercentInputOptions,
): UsePercentInputResult {
  const {
    locale = "en-US",
    precision = 2,
    min,
    max,
    positive,
    integer,
    required,
    validate,
    disabled,
    readOnly,
    placeholder,
    ...base
  } = options

  const asPercent = useCallback(
    (fraction: number) => `${formatPercent(fraction, { locale, precision })}%`,
    [locale, precision],
  )

  const ruleList = useMemo<ReadonlyArray<Rule<number>>>(
    () =>
      rules<number>(
        requiredRule<number>(required),
        minRule(min, asPercent),
        maxRule(max, asPercent),
        positiveRule(positive),
        integer && {
          rule: "integer",
          test: (v: number) => Number.isInteger(v * 100),
        },
        {
          rule: "precision",
          params: { precision },
          test: (v: number) => withinPrecision(v, precision),
        },
        custom<number>(validate),
      ),
    [required, min, max, positive, integer, precision, validate, asPercent],
  )

  const field = useField<number>({
    component: "PercentInput",
    emptyValue: 0,
    rules: ruleList,
    ...base,
    required,
    disabled,
    readOnly,
    serialize: (v) => String(v),
  })

  const { value, setValue } = field
  const ref = useRef<HTMLInputElement | null>(null)

  /**
   * Draft holds what the user is literally typing. Without it, "12." would be
   * parsed to 0.12 and reformatted to "12" the instant the dot is typed,
   * making a decimal impossible to enter.
   */
  const [draft, setDraft] = useState<string | null>(null)
  const display = draft ?? (value === 0 ? "" : formatPercent(value, { locale, precision }))

  const onChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      if (disabled || readOnly) return
      const text = e.currentTarget.value
      if (!ALLOWED.test(text)) return
      setDraft(text)
      setValue(parsePercent(text, { precision }))
    },
    [disabled, readOnly, setValue, precision],
  )

  // Committing on blur is what lets the draft exist without the value ever
  // disagreeing with it.
  const onBlur = useCallback(() => setDraft(null), [])

  const onPaste = useCallback(
    (e: ClipboardEvent<HTMLInputElement>) => {
      if (disabled || readOnly) return
      const text = clipboardText(e)
      if (!text) return
      e.preventDefault()
      const parsed = parsePastedPercent(text, { precision })
      if (parsed === null) return
      setDraft(null)
      setValue(parsed)
    },
    [disabled, readOnly, setValue, precision],
  )

  const inputProps = useMemo(
    () => ({
      ref,
      value: display,
      onChange,
      onBlur,
      onPaste,
      inputMode: "decimal" as const,
      autoComplete: "off" as const,
      disabled,
      readOnly,
      placeholder: placeholder ?? "0",
    }),
    [display, onChange, onBlur, onPaste, disabled, readOnly, placeholder],
  )

  return { ...field, display, inputProps }
}

/**
 * Percentage maths. Framework-free.
 *
 * Canonical value is a FRACTION: 0.125, not 12.5. The display is the
 * percentage; the value is what you multiply by. This is the off-by-100 bug
 * solved once — every codebase has shipped it at least once, usually in a
 * discount calculation.
 */

import { parseLooseNumber, scrub } from "@inputcn/core/paste"

export interface PercentFormatOptions {
  locale?: string
  /** Decimal places shown. Default 2, trailing zeros trimmed. */
  precision?: number
}

const formatterCache = new Map<string, Intl.NumberFormat>()

/** Fraction → the percentage string the user sees. `0.125` → `"12.5"`. */
export function formatPercent(
  fraction: number,
  { locale = "en-US", precision = 2 }: PercentFormatOptions = {},
): string {
  if (!Number.isFinite(fraction)) return ""
  const key = `${locale}|${precision}`
  let fmt = formatterCache.get(key)
  if (!fmt) {
    fmt = new Intl.NumberFormat(locale, {
      minimumFractionDigits: 0,
      maximumFractionDigits: precision,
    })
    formatterCache.set(key, fmt)
  }
  return fmt.format(round(fraction * 100, precision))
}

/** Percentage string → fraction. `"12.5"` → `0.125`. */
export function parsePercent(
  text: string,
  { precision = 2 }: PercentFormatOptions = {},
): number {
  const n = parseLooseNumber(text.replace("%", ""))
  if (n === null) return 0
  // Divide first, then round at the fraction's own scale, so 33.33% does not
  // come back as 0.3332999999999.
  return round(n / 100, precision + 2)
}

/**
 * Round to a fixed number of decimals without the float drift that
 * `toFixed` + `parseFloat` reintroduces at the boundaries.
 */
export function round(value: number, decimals: number): number {
  const f = 10 ** decimals
  return Math.round((value + Number.EPSILON) * f) / f
}

/** True when the fraction has no more than `precision` decimals as a percent. */
export function withinPrecision(fraction: number, precision: number): boolean {
  const asPercent = fraction * 100
  return Math.abs(round(asPercent, precision) - asPercent) < 1e-9
}

/**
 * Smart paste. Handles `"12.5%"`, `"12,5 %"`, `"0.125"` — but NOT by guessing:
 * a bare value ≤ 1 with a decimal point is ambiguous between "0.125 as a
 * fraction" and "0.125 percent", so we always read the number as a PERCENTAGE
 * unless a fraction is explicitly requested. Consistency beats cleverness here,
 * because the wrong guess silently produces a 100× error.
 */
export function parsePastedPercent(
  input: string,
  options: PercentFormatOptions & { asFraction?: boolean } = {},
): number | null {
  const text = scrub(input)
  if (!text) return null
  const n = parseLooseNumber(text.replace("%", ""))
  if (n === null) return null
  return options.asFraction
    ? round(n, (options.precision ?? 2) + 2)
    : round(n / 100, (options.precision ?? 2) + 2)
}
